.modal-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 10px;
  margin-top: 22px;
}

.completion-card {
  overflow: hidden;
  text-align: center;
}

.completion-card .panel-kicker {
  justify-content: center;
}

.completion-card h2 {
  font-size: clamp(36px, 6vw, 62px);
  letter-spacing: -0.06em;
}

.completion-card .modal-lede {
  margin-left: auto;
  margin-right: auto;
}

.completion-orbit {
  position: relative;
  width: 120px;
  height: 120px;
  margin: 2px auto 20px;
  border: 1px solid rgba(231, 189, 125, 0.22);
  border-radius: 50%;
}

.completion-orbit::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 160px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(231, 189, 125, 0.42), transparent);
  transform: translate(-50%, -50%) rotate(-28deg);
}

.completion-orbit::after {
  content: "";
  position: absolute;
  inset: -17px;
  border: 1px solid rgba(120, 220, 194, 0.12);
  border-radius: 50%;
}

.completion-star {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #ffe3ae;
  box-shadow: 0 0 28px 8px rgba(255, 183, 98, 0.55), 0 0 70px 20px rgba(255, 110, 43, 0.18);
  transform: translate(-50%, -50%);
}

.completion-planet {
  position: absolute;
  right: 8px;
  top: 20px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #79ddc6;
  box-shadow: 0 0 12px rgba(120, 220, 194, 0.7);
  animation: completionPulse 2.6s ease-in-out infinite;
}

.completion-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin-top: 24px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.07);
}

.completion-stats > div {
  padding: 15px 10px;
  background: #080e18;
}

.completion-stats span {
  display: block;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.13em;
  color: var(--dim);
}

.completion-stats b {
  display: block;
  margin-top: 7px;
  font-family: var(--mono);
  font-size: 19px;
  font-weight: 400;
  color: var(--gold-bright);
}

.ghost-btn {
  min-width: 130px;
  height: 46px;
  padding: 0 18px;
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #aeb7c1;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}

.ghost-btn:hover {
  color: var(--ink);
  border-color: rgba(231, 189, 125, 0.4);
  background: rgba(231, 189, 125, 0.04);
}

@keyframes completionPulse {
  0%, 100% { transform: scale(1); opacity: 0.7; }
  50% { transform: scale(1.35); opacity: 1; }
}

